import hashlib, gzip, json, os, re
files = {
 "GSE2553_series_matrix.txt.gz": "https://ftp.ncbi.nlm.nih.gov/geo/series/GSE2nnn/GSE2553/matrix/GSE2553_series_matrix.txt.gz",
 "GPL1977.annot.gz": "https://ftp.ncbi.nlm.nih.gov/geo/platforms/GPL1nnn/GPL1977/annot/GPL1977.annot.gz",
 "GPL1977_family.soft.gz": "https://ftp.ncbi.nlm.nih.gov/geo/platforms/GPL1nnn/GPL1977/soft/GPL1977_family.soft.gz",
 "GSE2553_family.soft.gz": "https://ftp.ncbi.nlm.nih.gov/geo/series/GSE2nnn/GSE2553/soft/GSE2553_family.soft.gz",
}
out={"method":"recompute sha-256 from the bytes on disk, and re-detect the accession identifiers inside the decompressed content",
     "independent_of":"the acquisition step's own log (acquisition-log.json); hashes here were recomputed in a new process from the files, not copied",
     "files":[]}
for name,url in files.items():
    if not os.path.exists(name):
        out["files"].append({"file":name,"status":"absent"}); continue
    h=hashlib.sha256()
    with open(name,"rb") as f:
        for chunk in iter(lambda: f.read(1<<20), b""):
            h.update(chunk)
    rec={"file":name,"url":url,"bytes":os.path.getsize(name),"sha256_recomputed":h.hexdigest(),"readable_as_gzip":None,"identifiers_found":{}}
    try:
        with gzip.open(name,"rb") as g:
            head=g.read(400000)
        rec["readable_as_gzip"]=True
        text=head.decode("utf-8","replace")
        rec["identifiers_found"]={
            "GSE2553": text.count("GSE2553")>0,
            "GPL1977": text.count("GPL1977")>0,
            "geo_accession_lines":[m for m in text.splitlines() if m.startswith("!Series_geo_accession") or m.startswith("!Platform_geo_accession")][:2],
        }
    except Exception as e:
        rec["readable_as_gzip"]=False; rec["gzip_error"]=f"{type(e).__name__}: {e}"
    out["files"].append(rec)
print(json.dumps(out, indent=2))
