import urllib.request, hashlib, json, datetime
UA={"User-Agent":"EviMed/1.0"}
urls={
"GSE2553_series_matrix.txt.gz":"https://ftp.ncbi.nlm.nih.gov/geo/series/GSE2nnn/GSE2553/matrix/GSE2553_series_matrix.txt.gz",
"GPL1977.annot.gz":"https://ftp.ncbi.nlm.nih.gov/geo/platforms/GPL1nnn/GPL1977/annot/GPL1977.annot.gz",
}
out={"what":"re-fetch the same URLs and hash the live bytes, without keeping them, to test whether the recorded hashes still equal what the source serves",
     "files":[]}
for name,u in urls.items():
    try:
        req=urllib.request.Request(u, headers=UA)
        with urllib.request.urlopen(req, timeout=90) as r:
            h=hashlib.sha256(); n=0
            while True:
                c=r.read(1<<20)
                if not c: break
                h.update(c); n+=len(c)
            out["files"].append({"file":name,"live_bytes":n,"live_sha256":h.hexdigest(),
                                 "live_last_modified":r.headers.get("Last-Modified"),
                                 "matches_recorded":None})
    except Exception as e:
        out["files"].append({"file":name,"error":f"{type(e).__name__}: {e}"})
rec={f["file"]:f["sha256"] for f in json.load(open("identity.json"))["sources"]}
for f in out["files"]:
    if "live_sha256" in f:
        f["matches_recorded"] = (f["live_sha256"] == rec.get(f["file"]))
        f["recorded_sha256"] = rec.get(f["file"])
out["checked_at"]=datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00","Z")
print(json.dumps(out, indent=2))
